-- =============================================================================
-- V10__update_pallets_and_contact_constraints.sql
-- Actualizaciones Incrementales WMS:
-- 1. Homologación de los 7 Tipos Oficiales de Tarima (Checks y Longitudes)
-- 2. Teléfono Opcional en Clientes, Contactos de Clientes y Contactos de Proveedores
-- 3. Corrección de Trigger de Actualización en Contactos de Proveedores
-- 4. Reestructuración de IDs Maestros a Formato Amigable de 8 Dígitos al Inicio (00000001-..., 00000101-...)
-- 5. Eliminación de Teléfonos Ficticios en Contactos Corporativos de Clientes
-- =============================================================================

SET search_path TO wms, public;

-- -----------------------------------------------------------------------------
-- 1. HOMOLOGACIÓN DE LOS 7 TIPOS OFICIALES DE TARIMA
-- -----------------------------------------------------------------------------
ALTER TABLE wms.warehouse_receptions ALTER COLUMN pallet_type TYPE VARCHAR(50);
ALTER TABLE wms.warehouse_reception_pallets ALTER COLUMN pallet_type TYPE VARCHAR(50);

ALTER TABLE wms.warehouse_receptions DROP CONSTRAINT IF EXISTS chk_wr_pallet_type;
ALTER TABLE wms.warehouse_receptions ADD CONSTRAINT chk_wr_pallet_type CHECK (pallet_type IN (
    'MADERA OWENS', 'MADERA ESTANDAR', 'PLASTICO NEGRO OWENS', 'PLASTICO AZUL',
    'TARIMA CHEP NACIONAL', 'TARIMA CHEP EXPORTACION', 'TARIMA PLASTICO NEGRO ESTANDAR',
    'MADERA_OWENS', 'MADERA_ESTANDAR', 'PLASTICO_NEGRO_OWENS', 'PLASTICO_AZUL',
    'TARIMA_CHEP_NACIONAL', 'TARIMA_CHEP_EXPORTACION', 'TARIMA_PLASTICO_NEGRO_ESTANDAR'
));

ALTER TABLE wms.warehouse_reception_pallets DROP CONSTRAINT IF EXISTS chk_wrp_pallet_type;
ALTER TABLE wms.warehouse_reception_pallets ADD CONSTRAINT chk_wrp_pallet_type CHECK (pallet_type IN (
    'MADERA OWENS', 'MADERA ESTANDAR', 'PLASTICO NEGRO OWENS', 'PLASTICO AZUL',
    'TARIMA CHEP NACIONAL', 'TARIMA CHEP EXPORTACION', 'TARIMA PLASTICO NEGRO ESTANDAR',
    'MADERA_OWENS', 'MADERA_ESTANDAR', 'PLASTICO_NEGRO_OWENS', 'PLASTICO_AZUL',
    'TARIMA_CHEP_NACIONAL', 'TARIMA_CHEP_EXPORTACION', 'TARIMA_PLASTICO_NEGRO_ESTANDAR'
));

-- -----------------------------------------------------------------------------
-- 2. TELÉFONOS OPCIONALES EN CLIENTES Y CONTACTOS
-- -----------------------------------------------------------------------------
ALTER TABLE wms.clients ALTER COLUMN phone DROP NOT NULL;
ALTER TABLE wms.client_contacts ALTER COLUMN phone DROP NOT NULL;
ALTER TABLE wms.supplier_contacts ALTER COLUMN phone DROP NOT NULL;

-- Corrección de trigger en supplier_contacts
DROP TRIGGER IF EXISTS trg_update_supplier_contacts ON wms.supplier_contacts;
CREATE TRIGGER trg_update_supplier_contacts
    BEFORE UPDATE ON wms.supplier_contacts
    FOR EACH ROW EXECUTE FUNCTION wms.fn_update_timestamp();

-- -----------------------------------------------------------------------------
-- 3. LIMPIEZA DE TABLAS Y RECARGA CON IDS AMIGABLES DE 8 DÍGITOS AL INICIO
-- -----------------------------------------------------------------------------

DELETE FROM wms.warehouse_outbound_items;
DELETE FROM wms.warehouse_outbounds;
DELETE FROM wms.warehouse_transfer_items;
DELETE FROM wms.warehouse_transfers;
DELETE FROM wms.warehouse_reception_seals;
DELETE FROM wms.warehouse_reception_pallets;
DELETE FROM wms.warehouse_receptions;
DELETE FROM wms.carrier_vehicle_metadata;
DELETE FROM wms.vehicle_seals;
DELETE FROM wms.inventory_movements;
DELETE FROM wms.incidences;
DELETE FROM wms.inventory_items;
DELETE FROM wms.products_sku;
DELETE FROM wms.client_contacts;
DELETE FROM wms.client_destinations;
DELETE FROM wms.carrier_preferred_clients;
DELETE FROM wms.clients;
DELETE FROM wms.supplier_commercial_terms;
DELETE FROM wms.supplier_addresses;
DELETE FROM wms.supplier_contacts;
DELETE FROM wms.suppliers;
DELETE FROM wms.carrier_vehicle_types;
DELETE FROM wms.carriers;
DELETE FROM wms.forklift_operators;
DELETE FROM wms.locations;
DELETE FROM wms.warehouse_sections;

